  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 8px 12px;
  border-radius: 8px;
  border: 1px solid var(--border, #E6E9EE);
  background: var(--btn-bg, #fff);
  color: var(--btn-text, #111827);
  cursor: pointer;
}
.btnPrimary {
  background: var(--primary, #2A9DF4);
  color: #fff;
  border: none;
}

