:root{
  /* Colors */
  --color-primary: #0B3D91;
  --color-accent: #FF6B4A;
  --color-bg: #F8FAFC;
  --color-surface: #FFFFFF;
  --color-muted: #6B7280;
  --color-success: #10B981;
  --color-warning: #FF9F1C;
  --color-danger: #EF4444;
  --muted-ghost: #E6E9EE;

  /* Typography */
  --font-sans: "Inter", "Noto Sans JP", system-ui, -apple-system, "Segoe UI", Roboto, "Hiragino Kaku Gothic ProN", "Meiryo", sans-serif;
  --font-size-base: 16px;
  --line-height-base: 1.5;

  /* Spacing */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;

  /* Radii / shadows */
  --radius-sm: 6px;
  --radius-md: 12px;
  --shadow-1: 0 1px 3px rgba(2,6,23,0.06);
  --shadow-2: 0 6px 20px rgba(11,61,145,0.08);

  /* Layout tokens */
  --topbar-height: 64px;
  --max-content-width: 1200px;
}

@import "./tokens.css";

/* Reset & base */
*{box-sizing:border-box}
html,body,#root{height:100%}
body{
  margin:0;
  font-family:var(--font-sans);
  font-size:var(--font-size-base);
  line-height:var(--line-height-base);
  background:var(--color-bg);
  color:#111827;
  -webkit-font-smoothing:antialiased;
  -moz-osx-font-smoothing:grayscale;
}

/* Layout helpers */
.container{max-width:var(--max-content-width);margin-inline:auto;padding-inline:var(--space-4)}
.layout-shell{display:flex;min-height:100vh;flex-direction:column}
.layout-main{display:flex;gap:var(--space-6);align-items:flex-start}

/* Utility */
.flex{display:flex}
.center{display:flex;align-items:center;justify-content:center}
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

/* Buttons (base) */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:8px 12px;border-radius:8px;border:0;font-weight:600;cursor:pointer}
.btn:focus{outline:3px solid rgba(11,61,145,0.12);outline-offset:2px}

/* Simple responsive container for main layout (used by header & pages) */
.main-frame{padding-top:var(--topbar-height)}
@media (max-width:768px){
  .container{padding-inline:var(--space-3)}
}

